<?php if ($orders === []): ?>
<div class="patient-empty-state"><i class="bi bi-box-seam" aria-hidden="true"></i><strong>No medicine orders found</strong><span>Orders linked to your prescriptions will appear here.</span></div>
<?php else: ?>
<div class="table-responsive patient-orders-table-wrap"><table class="table patient-orders-table"><caption class="sr-only">Patient medicine orders</caption><thead><tr><th>Order</th><th>Prescription</th><th>Medicines</th><th>Total</th><th>Payment</th><th>Delivery</th><th>Actions</th></tr></thead><tbody>
<?php foreach ($orders as $order): ?>
<tr><td data-label="Order"><strong class="patient-order-value" title="<?= esc($order['order_number'], 'attr') ?>"><?= esc($order['order_number']) ?></strong><small class="d-block text-muted"><?= esc($order['order_date_display']) ?></small></td><td data-label="Prescription"><span class="patient-order-value" title="<?= esc($order['prescription_number'], 'attr') ?>"><?= esc($order['prescription_number'] ?: 'Not linked') ?></span><small class="d-block text-muted"><?= esc($order['prescription_date_display']) ?></small></td><td data-label="Medicines"><span class="patient-order-value" title="<?= esc($order['medicine_summary'], 'attr') ?>"><?= esc($order['medicine_summary'] ?: 'No items') ?></span><small class="d-block text-muted"><?= count($order['items']) ?> item(s)</small></td><td data-label="Total"><strong><?= esc(number_format((float) $order['total_amount'], 2)) ?></strong></td><td data-label="Payment"><span class="badge patient-status-badge patient-status-<?= esc($order['payment_status']) ?>"><?= esc($order['payment_status_label']) ?></span></td><td data-label="Delivery"><span class="badge patient-status-badge patient-status-<?= esc($order['delivery_status']) ?>"><?= esc($order['delivery_status_label']) ?></span></td><td data-label="Actions"><div class="dropdown"><button class="btn btn-sm btn-primary dropdown-toggle" type="button" data-toggle="dropdown" aria-haspopup="true" aria-expanded="false">More Actions</button><div class="dropdown-menu dropdown-menu-right"><button class="dropdown-item patient-order-view" type="button" data-id="<?= (int) $order['id'] ?>" data-tracking-url="<?= esc($order['tracking_url'] ?? '', 'attr') ?>" data-toggle="modal" data-target="#patient-order-detail-modal">View order</button><?php if (! empty($order['tracking_url'])): ?><a class="dropdown-item" href="<?= esc($order['tracking_url'], 'attr') ?>" target="_blank" rel="noopener noreferrer"><i class="bi bi-box-arrow-up-right mr-2" aria-hidden="true"></i>Track Order</a><?php else: ?><span class="dropdown-item-text text-muted">Tracking not available</span><?php endif; ?><?php if (! empty($order['prescription_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/prescriptions?prescription_id=' . (int) $order['prescription_id']) ?>">View prescription</a><?php endif; ?><?php if (! empty($order['invoice_id'])): ?><a class="dropdown-item" href="<?= base_url('patient/invoices?invoice_id=' . (int) $order['invoice_id']) ?>">View invoice/payment</a><?php endif; ?></div></div></td></tr>
<?php endforeach; ?>
</tbody></table></div>
<?php endif; ?>
